(()=>{document.addEventListener('click',async event=>{const link=event.target.closest('a');if(!link||!link.href)return;const url=new URL(link.href,location.href);if(url.origin!==location.origin||!url.searchParams.has('download')||!/工作流|模板/.test(link.textContent))return;event.preventDefault();event.stopImmediatePropagation();if(link.dataset.downloading)return;link.dataset.downloading='1';const text=link.textContent;link.textContent='正在下载…';try{const r=await fetch(url.href,{cache:'no-store'});if(!r.ok)throw Error('下载失败，请重试');const content=await r.text();JSON.parse(content);const blob=new Blob([content],{type:'application/json;charset=utf-8'}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download='workflow-'+(url.pathname.match(/[a-f0-9]{8}-[a-f0-9-]{27}/)?.[0]?.slice(0,8)||'template')+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),60000);}catch(e){if(typeof toast==='function')toast(e.message);else alert(e.message);}finally{link.textContent=text;delete link.dataset.downloading;}},true);})();